fn print_theme_help() {
    println!("Provides commands regarding changing themes and styles of the app");
    println!();
    println!("Usage: executable theme <COMMAND>");
    println!();
    println!("Commands:");
    println!("  print-path      Prints the path to the user themes file [aliases: path]");
    println!("  print-default   Dumps the styles with the default values to be used as a reference and base for user custom themes [aliases: default]");
    println!("  write-defaults  Creates user custom themes file if doesn't exist then writes the default styles to it [aliases: write]");
    println!("  help            Print this message or the help of the given subcommand(s)");
    println!();
    println!("Options:");
    println!("  -h, --help  Print help");
}
```

`src/main.rs` lines 251-290 (main function):
```
fn main() {
    let config = Config::new();

    let args: Vec<String> = env::args().collect();
    let mut i = 1;

    while i < args.len() {
        if args[i].starts_with('-') {
            i += 1;
        } else {
            break;
        }
    }

    if i >= args.len() {
        print_help();
        std::process::exit(0);
    }

    let command = &args[i];

    match command.as_str() {
        "print-config" | "pc" => {
            print_config(&config);
        }
        "import-journals" | "imj" => {
            if i + 1 < args.len() {
                eprintln!("Error: import-journals requires a JSON file path");
                std::process::exit(1);
            } else {
                eprintln!("Error: import-journals requires a JSON file path");
                std::process::exit(1);
            }
        }
        "assign-priority" | "ap" => {
            eprintln!("Error: assign-priority requires entries");
            std::process::exit(1);
        }
        "theme" | "style" => {
            i += 1;
            if i >= args.len() {
                print_theme_help();
                std::process::exit(0);
            }

            let theme_command = &args[i];
            match theme_command.as_str() {
                "print-path" | "path" => {
                    print_theme_path(&config);
                }
                "print-default" | "default" => {
                    print_theme_defaults();
                }
                "write-defaults" | "write" => {
                    write_theme_defaults(&config);
                }
                "help" => {
                    print_theme_help();
                }
                _ => {
                    eprintln!("Error: Unknown theme command: {}", theme_command);
                    std::process::exit(1);
                }
            }
        }
        "help" => {
            print_help();
        }
        _ => {
            eprintln!("Error: Unknown command: {}", command);
            print_help();
            std::process::exit(1);
        }
    }
}
```

