fn main() {
    let config = Config::new();

    let args: Vec<String> = env::args().collect();
    let mut i = 1;

    while i < args.len() {
        if args[i].starts_with('-') {
            i += 1;
        } else {
            break;
        }
    }

    if i >= args.len() {
        print_help();
        std::process::exit(0);
    }

    let command = &args[i];

    match command.as_str() {
        "print-config" | "pc" => {
            print_config(&config);
        }
        "import-journals" | "imj" => {
            if i + 1 < args.len() {
                eprintln!("Error: import-journals requires a JSON file path");
