        }
        "theme" | "style" => {
            i += 1;
            if i >= args.len() {
                print_theme_help();
                std::process::exit(0);
            }

            let theme_command = &args[i];
            match theme_command.as_str() {
                "print-path" | "path" => {
                    print_theme_path(&config);
                }
                "print-default" | "default" => {
                    print_theme_defaults();
                }
                "write-defaults" | "write" => {
                    write_theme_defaults(&config);
                }
                "help" => {
                    print_theme_help();
                }
                _ => {
                    eprintln!("Error: Unknown theme command: {}", theme_command);
                    std::process::exit(1);
                }
            }
        }
        "help" => {
            print_help();
        }
        _ => {
            eprintln!("Error: Unknown command: {}", command);
            print_help();
            std::process::exit(1);
        }
    }
}
